llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Omadacycline, a glycylcycline sharing the same tetracycline core and a similar C9 side-chain motif as the query, has an absolute oral bioavailability of 34.5% in humans, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C62"],
      "claim": "Tetracycline, the parent tetracycline scaffold, has oral bioavailability >70% in humans, indicating that the tetracycline class can achieve high oral absorption despite polar functionality.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Loperamide has a very low absolute oral bioavailability of 0.3% in humans, a direct low-F measurement with a high assay-transfer score, but its mechanism is dominated by P-gp efflux and first-pass metabolism in a non-tetracycline opioid scaffold, limiting direct extrapolation to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C31"],
      "claim": "Butorphanol has an absolute oral bioavailability of only 5–17% in humans, providing additional low-F evidence with high transferability, but it is structurally and mechanistically distant from the tetracycline/glycylcycline class.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest chemical evidence, omadacycline, shows 34.5% absolute oral bioavailability in humans, and the parent tetracycline class shows >70% oral bioavailability, supporting F ≥ 20%. The low-F evidence from loperamide and butorphanol has high assay-transfer scores but comes from structurally unrelated scaffolds with strong P-gp/first-pass liabilities, so it does not override the tetracycline-class data. Prediction: high.",
  "evidence_gaps": [
    "No direct eravacycline oral bioavailability record is present in the supplied evidence; the prediction relies on transfer from omadacycline and tetracycline analogues.",
    "One omadacycline record (C72) reports an absolute bioavailability estimate of 0.00663, which conflicts with the majority of omadacycline records reporting 34.5%; this inconsistency is unresolved.",
    "Food effects can markedly alter tetracycline-class absorption, as seen in the omadacycline fed-state record, so the prediction is most applicable to fasted oral conditions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

